# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BASİT HARMONİK HAREKETTE TEMEL DENKLEMLER VE GRAFİKLER</text>\n  <rect x="25" y="46" width="320" height="196" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Konuma ve Zamana Bağlı Bağıntılar</text>\n  <text x="42" y="96" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">Uzanım:</tspan> x = r · sin(ω · t)   [ω = 2π / T]</text>\n  <text x="42" y="122" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">Maksimum Hız (O\'da):</tspan> v_max = ω · r</text>\n  <text x="42" y="148" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">Herhangi bir x\'te Hız:</tspan> v = ω · kök(r² - x²)</text>\n  <text x="42" y="174" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">Anlık İvme:</tspan> a = -ω² · x   |   a_max = ω² · r</text>\n  <text x="42" y="200" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">Çağırıcı Kuvvet:</tspan> F = -m · ω² · x</text>\n  <text x="185" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">F ve a daima denge noktasına (O) yöneliktir!</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Kuvvet - Uzanım (F - x) Grafiği</text>\n  <line x1="400" y1="150" x2="635" y2="150" stroke="#0f172a" stroke-width="2"/>\n  <line x1="517" y1="82" x2="517" y2="218" stroke="#0f172a" stroke-width="2"/>\n  <line x1="430" y1="95" x2="604" y2="205" stroke="#dc2626" stroke-width="3"/>\n  <text x="642" y="154" font-size="11" font-weight="bold" fill="#0f172a">+x</text>\n  <text x="523" y="90" font-size="11" font-weight="bold" fill="#0f172a">+F</text>\n  <text x="422" y="166" font-size="11" font-weight="bold" fill="#dc2626">-r</text>\n  <text x="598" y="166" font-size="11" font-weight="bold" fill="#dc2626">+r</text>\n  <text x="530" y="102" font-size="10" font-weight="bold" fill="#dc2626">+F_max</text>\n  <text x="468" y="212" font-size="10" font-weight="bold" fill="#dc2626">-F_max</text>\n  <text x="517" y="233" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">Eğim: tan(α) = F / x = -m · ω² = -k</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">YAY SARKACI PERİYODU (T = 2π · kök(m / k)) VE YAY BAĞLANTILARI</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Yay Sarkacı Özellikleri</text>\n  <text x="40" y="98" font-size="12" font-weight="bold" fill="#14532d">T = 2π · kök(m / k)</text>\n  <text x="40" y="122" font-size="11" fill="#14532d">• Kütle (m) artarsa T artar.</text>\n  <text x="40" y="142" font-size="11" fill="#14532d">• Yay sabiti (k) artarsa T azalır.</text>\n  <text x="40" y="162" font-size="11" fill="#14532d">• Çekim ivmesine (g) bağlı değil!</text>\n  <text x="40" y="182" font-size="11" fill="#14532d">• Ay\'da ve Dünya\'da T aynıdır.</text>\n  <rect x="40" y="194" width="175" height="32" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="127" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Kodlama: T = 2π · kök(m / k)</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Seri Bağlı Yaylar</text>\n  <text x="262" y="98" font-size="12" font-weight="bold" fill="#1e3a8a">1 / k_eş = 1 / k₁ + 1 / k₂</text>\n  <text x="262" y="122" font-size="11" fill="#1e3a8a">• Özdeş iki yay: k_eş = k / 2</text>\n  <text x="262" y="142" font-size="11" fill="#1e3a8a">• Yay sistemi yumuşar.</text>\n  <text x="262" y="162" font-size="11" fill="#1e3a8a">• Her yaydaki kuvvet aynıdır.</text>\n  <text x="262" y="182" font-size="11" fill="#1e3a8a">• Periyot (T) büyür.</text>\n  <rect x="262" y="194" width="175" height="32" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="349" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">k_eş = (k₁ · k₂) / (k₁ + k₂)</text>\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Paralel Bağlı Yaylar</text>\n  <text x="485" y="98" font-size="12" font-weight="bold" fill="#581c87">k_eş = k₁ + k₂</text>\n  <text x="485" y="122" font-size="11" fill="#581c87">• Özdeş iki yay: k_eş = 2k</text>\n  <text x="485" y="142" font-size="11" fill="#581c87">• Yay sistemi sertleşir.</text>\n  <text x="485" y="162" font-size="11" fill="#581c87">• Uzama miktarları eşittir.</text>\n  <text x="485" y="182" font-size="11" fill="#581c87">• Periyot (T) küçülür.</text>\n  <rect x="485" y="194" width="175" height="32" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="572" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Yay n parçaya bölünürse: n·k</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BASİT SARKAÇ PERİYODU (T = 2π · kök(L / g)) VE ETKİN İVME</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">Basit Sarkaç Bağıntısı</text>\n  <text x="42" y="96" font-size="12" font-weight="bold" fill="#7f1d1d">T = 2π · kök(L / g)   (α &lt;= 5°)</text>\n  <text x="42" y="122" font-size="11" fill="#7f1d1d">• İp boyu (L) artarsa periyot (T) artar.</text>\n  <text x="42" y="144" font-size="11" fill="#7f1d1d">• Çekim ivmesi (g) artarsa periyot (T) azalır.</text>\n  <text x="42" y="166" font-size="11" fill="#7f1d1d">• Cismin kütlesine (m) bağlı değildir!</text>\n  <text x="42" y="188" font-size="11" fill="#7f1d1d">• Ay\'a götürülen sarkacın g\'si azalır, T\'si artar.</text>\n  <rect x="42" y="200" width="280" height="30" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="182" y="219" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Kodlama: TOLGA (T = 2π · kök(L / g))</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Asansör İçinde Sarkaç (g_etkin)</text>\n  <text x="378" y="96" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Sabit hızlı asansör (a = 0):</tspan></text>\n  <text x="388" y="114" font-size="11" fill="#1e3a8a">g_etkin = g  →  T değişmez.</text>\n  <text x="378" y="140" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Yukarı hızlanan / Aşağı yavaşlayan:</tspan></text>\n  <text x="388" y="158" font-size="11" fill="#1e3a8a">g_etkin = g + a  →  Periyot (T) azalır.</text>\n  <text x="378" y="184" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Aşağı hızlanan / Yukarı yavaşlayan:</tspan></text>\n  <text x="388" y="202" font-size="11" fill="#1e3a8a">g_etkin = g - a  →  Periyot (T) artar.</text>\n  <text x="517" y="228" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Çivilere takılan sarkaçta: T_ort = (T₁ + T₂) / 2</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
